import java.util.*; public class StopWordFrequencyReport{static void printFilteredWordFrequency(String s){Set<String> q=new HashSet<>(Arrays.asList("the","was","and","a","is","of","in"));Map<String,Integer> m=new HashMap<>();for(String w:s.toLowerCase().replace(".","").replace(",","").split("\\s+"))if(!q.contains(w))m.put(w,m.getOrDefault(w,0)+1);m.entrySet().stream().sorted((a,b)->b.getValue()-a.getValue()).forEach(e->System.out.println(e.getKey()+": "+e.getValue()));}public static void main(String[] z){printFilteredWordFrequency(new Scanner(System.in).nextLine());}}